        super().__init__()
        self.max_width = max_width
        self.width_capped = bool(max_width)
        self._trace = trace

    def get_css_variables(self) -> dict[str, str]:
        """Use the terminal's default background instead of Textual's dark theme.

        Textual paints a dark (#121212) background over the whole screen by
        default. Making these transparent lets the user's terminal colors show
        through, so the app doesn't impose a brownish tint.
        """
        variables = super().get_css_variables()
        for name in ("background", "surface", "panel"):
            variables[name] = "transparent"
        return variables

    def compose(self) -> ComposeResult:
        yield Header()
        yield NonAnimatedRichLog(highlight=True, markup=False, wrap=True, id="trace-log")
        yield Footer()

    def _render(self) -> None:
        log = self.query_one(RichLog)
        self.sub_title = f"{self.size.width}×{self.size.height} · {self.SUB_TITLE}"
        log.clear()
        console = Console(
            file=RichLogFile(log),
            soft_wrap=True,
            color_system="truecolor",
            width=max(1, log.scrollable_content_region.width),
        )
        viewer.render_trace_to_console(
            console, self._trace, full_width=True
        )

    def on_mount(self) -> None:
        self.set_transcript_width(self.query_one(RichLog), self.max_width)
        viewer.args.show_all = True
        self.call_after_refresh(self._render)

    def action_toggle_width(self) -> None:
        self.width_capped = not self.width_capped
        self.set_transcript_width(self.query_one(RichLog), (self.max_width or 160) if self.width_capped else 0)
        self.call_after_refresh(self._render)

